class SQLQueryBuilder:

    WHERE_CLAUSE_SEPARATOR = " WHERE "
    AND_SEPARATOR = " AND "
    COMMA_SEPARATOR = ", "
    SELECT_KEYWORD = "SELECT"
    FROM_KEYWORD = "FROM"
    INSERT_KEYWORD = "INSERT INTO"
    VALUES_KEYWORD = "VALUES"
    DELETE_KEYWORD = "DELETE FROM"
    UPDATE_KEYWORD = "UPDATE"
    SET_KEYWORD = "SET"

    @classmethod
    def _format_where_clause(cls, where):
        if not where:
            return ""
        conditions = [f"{k}='{v}'" for k, v in where.items()]
        return cls.WHERE_CLAUSE_SEPARATOR + cls.AND_SEPARATOR.join(conditions)

    @classmethod
    def _format_columns(cls, columns):
        if columns == '*':
            return '*'
        return cls.COMMA_SEPARATOR.join(columns)

    @classmethod
    def _format_data_pairs(cls, data):
        return cls.COMMA_SEPARATOR.join(f"{k}='{v}'" for k, v in data.items())

    @classmethod
    def select(cls, table, columns='*', where=None):
        formatted_columns = cls._format_columns(columns)
        query = f"{cls.SELECT_KEYWORD} {formatted_columns} {cls.FROM_KEYWORD} {table}"
        query += cls._format_where_clause(where)
        return query

    @classmethod
    def insert(cls, table, data):
        keys = cls.COMMA_SEPARATOR.join(data.keys())
        values = cls.COMMA_SEPARATOR.join(f"'{v}'" for v in data.values())
        return f"{cls.INSERT_KEYWORD} {table} ({keys}) {cls.VALUES_KEYWORD} ({values})"

    @classmethod
    def delete(cls, table, where=None):
        query = f"{cls.DELETE_KEYWORD} {table}"
        query += cls._format_where_clause(where)
        return query

    @classmethod
    def update(cls, table, data, where=None):
        update_str = cls._format_data_pairs(data)
        query = f"{cls.UPDATE_KEYWORD} {table} {cls.SET_KEYWORD} {update_str}"
        query += cls._format_where_clause(where)
        return query
